  // per row at medium (6), three at large (4), four at x-large/xx-large (3),
  // and six at xxx-large (2).
  cardColumn: {
    gridColumn: "span 12",
    "@container (min-width: 480px)": {
      gridColumn: "span 6",
    },
    "@container (min-width: 640px)": {
      gridColumn: "span 4",
    },
    "@container (min-width: 1024px)": {
      gridColumn: "span 3",
    },
    "@container (min-width: 1920px)": {
      gridColumn: "span 2",
