const OverVideo = (args) => {
  const OverVideoDemo = () => {
    const containerRef = useRef<HTMLDivElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const [playing, setPlaying] = useState(false);
    const [recording, setRecording] = useState(false);
    const [nightMode, setNightMode] = useState(false);
    const [fullscreen, setFullscreen] = useState(false);

    const togglePlay = useCallback(() => {
      const video = videoRef.current;
      if (!video) {
        return;
      }
      if (video.paused) {
        void video.play();
        setPlaying(true);
      } else {
        video.pause();
        setPlaying(false);
      }
    }, []);

    const toggleFullscreen = useCallback(() => {
      const container = containerRef.current;
      if (!container) {
        return;
      }
      if (document.fullscreenElement) {
        void document.exitFullscreen();
        setFullscreen(false);
      } else {
        void container.requestFullscreen();
        setFullscreen(true);
      }
    }, []);

    const start: VideoControlBarGroup[] = [
      {
        key: "playback",
        items: [
          {
            key: "play",
            label: playing ? "Pause stream" : "Start stream",
            icon: playing ? <PauseFilled /> : <PlayFilled />,
            active: playing,
            onClick: togglePlay,
          },
        ],
      },
      {
        key: "snapshot",
        items: [
          {
            key: "snapshot",
            label: "Take a snapshot",
            icon: <CameraRegular />,
          },
        ],
      },
      {
        key: "record-cluster",
        segmented: true,
        items: [
          {
            key: "record",
            label: recording ? "Stop recording" : "Start recording",
            icon: <RecordRegular />,
            tone: "danger",
            active: recording,
            onClick: () => setRecording((value) => !value),
          },
          {
            key: "storage",
            label: "Select storage",
            icon: <StorageRegular />,
          },
        ],
      },
      {
        key: "ir",
        items: [
          {
            key: "ir",
            label: "IR light",
            icon: <WeatherMoonRegular />,
            active: nightMode,
            onClick: () => setNightMode((value) => !value),
          },
        ],
      },
      {
        key: "osd",
        items: [
          {
            key: "osd",
            label: "Onscreen controls",
            icon: <OptionsRegular />,
          },
        ],
      },
    ];

    const end: VideoControlBarGroup[] = [
      {
        key: "settings",
        items: [
          {
            key: "settings",
            label: "Live view settings",
            icon: <SettingsRegular />,
            hasMenu: true,
            menuItems: [
              { key: "quality", label: "Stream quality" },
              { key: "overlay", label: "Overlay settings" },
              { key: "rotation", label: "Image rotation" },
            ],
          },
        ],
      },
      {
        key: "view-cluster",
        segmented: true,
        items: [
          { key: "resolution", label: "Full resolution", text: "1:1" },
          {
            key: "expand",
            label: "Expanded live view",
            icon: <RectangleLandscapeRegular />,
          },
          {
            key: "fullscreen",
            label: fullscreen ? "Exit full screen" : "Full screen",
            icon: fullscreen ? (
              <FullScreenMinimizeRegular />
            ) : (
              <FullScreenMaximizeRegular />
            ),
            active: fullscreen,
            onClick: toggleFullscreen,
          },
        ],
      },
    ];

    return (
      <div
        ref={containerRef}
        style={{
          position: "relative",
          width: "100%",
          height: 480,
          overflow: "hidden",
          backgroundColor: "#000",
          display: "block",
          lineHeight: 0,
        }}
      >
        <video
          ref={videoRef}
          autoPlay
          loop
          muted
          playsInline
          preload="auto"
          onPlay={() => setPlaying(true)}
          onPause={() => setPlaying(false)}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            display: "block",
            filter: nightMode ? "grayscale(1) brightness(1.3)" : undefined,
            transition: "filter 200ms ease",
          }}
        >
          {SAMPLE_VIDEO_SOURCES.map((source) => (
            <source key={source} src={source} type="video/mp4" />
          ))}
          <track kind="captions" />
        </video>

        {recording ? (
          <div
            style={{
              position: "absolute",
              top: 16,
              left: 16,
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "4px 10px",
              borderRadius: 4,
              backgroundColor: "rgba(0, 0, 0, 0.6)",
              color: "#fff",
              fontSize: 12,
              fontWeight: 600,
            }}
          >
            <span
              style={{
                width: 8,
                height: 8,
                borderRadius: "50%",
                backgroundColor: "#e00",
              }}
            />
            REC
          </div>
        ) : null}

        <div
          style={{
            position: "absolute",
            left: 12,
            right: 12,
            bottom: 12,
          }}
        >
          <VideoControlBar {...args} start={start} end={end} />
        </div>
      </div>
    );
  };

  return <OverVideoDemo />;
};

const OverLiveFeed = (args) => {
  const OverLiveFeedDemo = () => {
    const containerRef = useRef<HTMLDivElement>(null);
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const [playing, setPlaying] = useState(true);
    const [recording, setRecording] = useState(false);
    const [nightMode, setNightMode] = useState(false);
    const [fullscreen, setFullscreen] = useState(false);

    // Cross-origin YouTube embeds can't be driven through the DOM, but the
    // IFrame Player API accepts JSON commands over postMessage when the embed
    // is loaded with `enablejsapi=1`.
    const postCommand = useCallback((func: string) => {
      iframeRef.current?.contentWindow?.postMessage(
        JSON.stringify({ event: "command", func, args: [] }),
        "*"
      );
    }, []);

    const togglePlay = useCallback(() => {
      setPlaying((value) => {
        const next = !value;
        postCommand(next ? "playVideo" : "pauseVideo");
        return next;
      });
    }, [postCommand]);

    const toggleFullscreen = useCallback(() => {
      const container = containerRef.current;
      if (!container) {
        return;
      }
      if (document.fullscreenElement) {
        void document.exitFullscreen();
        setFullscreen(false);
      } else {
        void container.requestFullscreen();
        setFullscreen(true);
      }
    }, []);

    const start: VideoControlBarGroup[] = [
