            active: recording,
            onClick: () => setRecording((value) => !value),
          },
          {
            key: "storage",
            label: "Select storage",
            icon: <StorageRegular />,
          },
        ],
      },
      {
        key: "ir",
        items: [
          {
            key: "ir",
            label: "IR light",
            icon: <WeatherMoonRegular />,
            active: nightMode,
            onClick: () => setNightMode((value) => !value),
          },
        ],
      },
      {
        key: "osd",
        items: [
          {
            key: "osd",
            label: "Onscreen controls",
            icon: <OptionsRegular />,
          },
        ],
      },
    ];

    const end: VideoControlBarGroup[] = [
      {
        key: "settings",
        items: [
          {
            key: "settings",
            label: "Live view settings",
            icon: <SettingsRegular />,
            hasMenu: true,
            menuItems: [
              { key: "quality", label: "Stream quality" },
              { key: "overlay", label: "Overlay settings" },
              { key: "rotation", label: "Image rotation" },
            ],
          },
        ],
      },
      {
        key: "view-cluster",
        segmented: true,
        items: [
          { key: "resolution", label: "Full resolution", text: "1:1" },
          {
            key: "expand",
            label: "Expanded live view",
            icon: <RectangleLandscapeRegular />,
          },
          {
            key: "fullscreen",
            label: fullscreen ? "Exit full screen" : "Full screen",
            icon: fullscreen ? (
              <FullScreenMinimizeRegular />
            ) : (
              <FullScreenMaximizeRegular />
            ),
            active: fullscreen,
            onClick: toggleFullscreen,
          },
        ],
      },
    ];

    return (
      <div
        ref={containerRef}
        style={{
          position: "relative",
          width: "100%",
          height: 480,
          overflow: "hidden",
          backgroundColor: "#000",
          display: "block",
          lineHeight: 0,
        }}
      >
        <iframe
          ref={iframeRef}
          title="Kristianstad Stora Torg live webcam"
          src={LIVE_FEED_EMBED}
          allow="autoplay; encrypted-media; picture-in-picture"
          allowFullScreen
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            border: 0,
            // Scale the 16:9 embed up so the letterboxing is cropped by the
            // container's overflow, mimicking an object-fit: cover feed.
            transform: "scale(1.35)",
            transformOrigin: "center",
            filter: nightMode ? "grayscale(1) brightness(1.3)" : undefined,
            transition: "filter 200ms ease",
          }}
        />

        <div
          style={{
            position: "absolute",
